function parseLLMJson(text) {
  if (!text) throw new Error("Respuesta vacía del LLM");
  text = String(text).trim();
  try { return JSON.parse(text); } catch (e) {}
  const fence = text.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  if (fence) { try { return JSON.parse(fence[1]); } catch (e) {} }
  const obj = text.match(/\{[\s\S]*\}/);
  if (obj) { try { return JSON.parse(obj[0]); } catch (e) {} }
  throw new Error("No se pudo extraer JSON válido");
}

const original = $('Normalización').item.json;
const raw = $json.choices?.[0]?.message?.content || $json.content || "";

let analisis;
let errorAnalisis = null;
try {
  analisis = parseLLMJson(raw);
} catch (e) {
  errorAnalisis = e.message;
  analisis = {
    sentimiento: "neutro",
    temas: [],
    tipo_detectado: "otro",
    score_llm: 0,
    insight: "Error al analizar: " + e.message
  };
}

const tipoPeso = { testimonio: 2.0, logro: 1.5, pregunta_tecnica: 1.5, otro: 0.5 };
const rawScore = Number(analisis.score_llm);
const scoreLLM = Number.isFinite(rawScore) ? Math.max(0, Math.min(10, rawScore)) : 0;
const senalTipo = tipoPeso[analisis.tipo_detectado] || 0.5;
let scoreFinal = 0.75 * scoreLLM + 0.25 * senalTipo;
scoreFinal = Math.max(0, Math.min(10, Number(scoreFinal.toFixed(2))));

const sentimiento = analisis.sentimiento || "neutro";
const tipoDetectado = analisis.tipo_detectado || "otro";
const sentimientoPositivo = ["muy_positivo", "positivo"].includes(sentimiento);
const elegible = sentimientoPositivo && scoreFinal >= 6 && ["testimonio", "pregunta_tecnica", "logro"].includes(tipoDetectado);

let motivo_descarte = "";
if (!elegible) {
  if (errorAnalisis) motivo_descarte = "error_analisis";
  else if (!["testimonio", "pregunta_tecnica", "logro"].includes(tipoDetectado)) motivo_descarte = "tipo_no_elegible";
  else if (!sentimientoPositivo) motivo_descarte = "sentimiento_no_positivo";
  else if (scoreFinal < 6) motivo_descarte = "score_bajo";
  else motivo_descarte = "otro";
}

return {
  json: {
    execution_id: original.execution_id,
    interaction_id: original.interaction_id,
    autor: original.autor,
    canal: original.canal,
    texto_original: original.texto,
    origen_comunidad: original.origen_comunidad,
    periodo_referencia: original.periodo_referencia,
    tipo_original: original.tipo_original,
    sentimiento,
    temas: Array.isArray(analisis.temas) ? analisis.temas : [],
    tipo_detectado: tipoDetectado,
    score_llm: scoreLLM,
    score_final: scoreFinal,
    insight: analisis.insight || "",
    elegible,
    motivo_descarte,
    timestamp_scoring: new Date().toISOString()
  }
};

const item = $input.item.json;
return {
